func (v *ValidateRule) Validate(ctx context.Context, pm interface{}, opts ...db.ValidateOpt) error {
	m, ok := pm.(*Rule)
	if !ok {
		switch t := pm.(type) {
		case nil:
			return nil
		default:
			return fmt.Errorf("Expected type *Rule got type %s", t)
		}
	}
	if m == nil {
		return nil
	}
	if fv, exists := v.FldValidators["actions"]; exists {
		vOpts := append(opts, db.WithValidateField("actions"))
		if err := fv(ctx, m.GetActions(), vOpts...); err != nil {
			return err
		}
	}
	if fv, exists := v.FldValidators["conditions"]; exists {
		vOpts := append(opts, db.WithValidateField("conditions"))
		if err := fv(ctx, m.GetConditions(), vOpts...); err != nil {
			return err
		}
	}
	if fv, exists := v.FldValidators["description"]; exists {
		vOpts := append(opts, db.WithValidateField("description"))
		if err := fv(ctx, m.GetDescription(), vOpts...); err != nil {
			return err
		}
	}
	if fv, exists := v.FldValidators["name"]; exists {
		vOpts := append(opts, db.WithValidateField("name"))
		if err := fv(ctx, m.GetName(), vOpts...); err != nil {
			return err
		}
	}
	return nil
}

